// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newSlippage) public {
        // Ensure the caller is the owner to avoid revert on setThresholds
        vm.prank(c.owner());
        c.setThresholds(newSlippage);
        // After a claim (any address, any amount), the getter must return the last set value.
        // The claim may revert arbitrarily, but we still check the getter afterward.
        address claimer = address(0x1234);
        uint256 amount = 0;
        (bool ok, ) = address(c).call(abi.encodeCall(c.claim, (claimer, amount)));
        // The general rule: the slippageThresholdGmxBps getter equals the last input
        assertTrue(c.slippageThresholdGmxBps() == newSlippage);
    }
}

